contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }
    function testFuzz_property(address nonLender, address approvalTarget, uint256 loanID) public {
        vm.assume(nonLender != address(0));
        vm.assume(loanID < type(uint256).max);
        vm.prank(nonLender);
        try c.approveTransfer(approvalTarget, loanID) {
            vm.assume(approvalTarget != address(0));
        } catch {
        }
        assertTrue(c.approvals(loanID) == address(0));
    }
}
